const brief = $("Read Today's Brief").first().json;

function pullFromExtract(nodeName) {
  const item = $(nodeName).first();
  const base64 = item.json.base64_data || item.json.data;
  const mime = item.json.mimeType 
            || item.binary?.data?.mimeType 
            || 'image/png';
  if (!base64) {
    throw new Error(`${nodeName} did not produce base64_data. Check the Extract node's Destination Key.`);
  }
  return { base64, mime };
}

const ref1 = pullFromExtract('Extract Ref 1');
const ref2 = pullFromExtract('Extract Ref 2');
const logo = pullFromExtract('Extract Logo');

return [{
  json: {
    brief,
    ref1_base64: ref1.base64, ref1_mime: ref1.mime,
    ref2_base64: ref2.base64, ref2_mime: ref2.mime,
    logo_base64: logo.base64, logo_mime: logo.mime,
  }
}];

